const SECTION = r => {
  for (const m of MENU) { if (m.href === r) return m.k; if (m.items && m.items.some(i => r === i[0] || r.startsWith(i[0] + '-'))) return m.k; }
  if (r.startsWith('news')) return 'news';
  if (r.startsWith('portfolio') || r.startsWith('product')) return 'dist';
  return '';
};

