  return phero({ crumbs: [['partners', 'Дистрибуція'], ['portfolio', 'Продуктовий портфель'], ['portfolio-' + s[0], s[1]], [0, p.n]], sub: ['dist', 'portfolio'], title: p.n, tag: p.br, lead: `${s[1]} · ${p.pack}` })
    + sec(`<div class="pcard2"><div class="pt-img">${PACK[p.f](pcol(p.br))}</div><div class="box"><span class="lbl">${DEMO}</span>
      <div class="kv"><span>Бренд</span><b>${p.br}</b></div><div class="kv"><span>Сектор</span><b>${s[1]}</b></div><div class="kv"><span>Фасування</span><b>${p.pack}</b></div><div class="kv"><span>Кратність замовлення</span><b>у порталі: ящик / палета</b></div>
      <p style="margin-top:18px">Опис, характеристики, регламенти застосування та документи підтягуються з картки товару в обліковій системі.</p>
      <div class="s-cta"><a class="btn btn-y btn-lg" href="#login">Замовити в порталі ${arr}</a><a class="btn btn-ghost btn-lg" href="#contacts">Де купити</a></div></div></div>`)
    + (rel.length ? sec(head2('Інші товари сектору', '', `<a class="lnk" href="#portfolio-${s[0]}">Усі товари ${arr}</a>`) + `<div class="plgrid">${rel.map(prodTile).join('')}</div>`) : '');
