P.complex = () => phero({ crumbs: [['complex', 'Виробничо-складський комплекс'], [0, 'Про комплекс']], tag: 'Виробничо-складський комплекс', title: 'Комплекс «Родниківка»', lead: 'Складська, логістична та виробнича база, що спеціалізується на фасуванні засобів захисту рослин, добрив та наданні послуг зі зберігання продукції.', img: '02', sub: ['complex', 'complex'] })
