  + sec(`<div class="split"><div class="box"><span class="lbl">Технічні можливості</span><h3 style="font-size:26px">7 ліній автоматичного фасування</h3><p>Пакуємо продукцію у тару об’ємом від 1,2 мл до 1 літра. Виробничий комплекс обладнаний сучасними фасувальними лініями та складськими приміщеннями, що відповідають усім нормам зберігання.</p><div class="chips" style="margin-top:18px"><span class="y">Сипучі: порошки, гранули</span><span>Рідкі: емульсії, суспензії, розчинні концентрати</span><span>Інші види речовин</span></div></div>
      <div class="dc-img dc-pack" style="border-radius:12px;aspect-ratio:auto;min-height:280px"><div class="pk-row">${PACK.sachet('#0D3C46').replace('<svg', '<svg style="height:54px"')}${PACK.flask('#0D3C46').replace('<svg', '<svg style="height:80px"')}${PACK.bottle('#0D3C46').replace('<svg', '<svg style="height:104px"')}${PACK.can('#0D3C46').replace('<svg', '<svg style="height:150px"')}</div><div class="pk-sc"><span>1,2 мл</span><i></i><span>1 л</span></div></div></div>`)
  + sec(head2('Ми фасуємо в') + `<div class="g3">${[['Пакет-саше', 'Упаковка з багатошарової полімерної плівки з трьома або чотирма швами. Комбінації PET, PE, PAPE, CPP та інші. Одинарні або парні пакети з перфорацією.', 'Висота 90–190 мм · ширина 60–125 мм'], ['Пляшки та флакони', 'Пластикова упаковка з плоским або увігнутим дном для рідких і в’язких речовин, зі стікеруванням етикетки: одношарові, двошарові, з друком на звороті.', 'Етикетка: висота 25–150 мм · ширина 90–320 мм'], ['Кришки', 'Верхня частина, що герметично закриває флакони або пляшки. Пластик різних кольорів з можливістю нанесення логотипу.', 'Стандарти ЄС: DIN 60, DIN 63, DIN 46, КБ-2']].map(t => card({ h: t[0], p: t[1], more: `<div class="chips" style="margin-top:16px"><span>${t[2]}</span></div>` })).join('')}</div>`)
