    const inp = $('input', o), res = $('.srch-r', o);
    const run = () => { const q = inp.value.trim().toLowerCase(); if (!q) { res.innerHTML = ''; return; } const r = INDEX().filter(x => (x[1] + ' ' + x[2]).toLowerCase().includes(q)).slice(0, 12); res.innerHTML = r.length ? r.map(x => `<a href="#${x[0]}"><b>${x[1]}</b><span>${x[2]}</span></a>`).join('') : `<div class="srch-e">Нічого не знайдено</div>`; };
