function resolve(h) {
  if (P[h]) return () => P[h]();
  const i = h.indexOf('-');
  if (i > 0) { const base = h.slice(0, i) + '-*'; if (P[base]) return () => P[base](h.slice(i + 1)); }
  if (h.startsWith('brand-') && P[h]) return () => P[h]();
  return null;
}
function render() {
  let h = location.hash.slice(1) || 'home';
  if (h === 'main') h = 'home';
  let fn = resolve(h);
  if (!fn) { const el = document.getElementById(h); if (el) { el.scrollIntoView({ behavior: 'smooth' }); return; } h = 'home'; fn = resolve('home'); }
  $('#hdr').innerHTML = header(h);
  $('#main').innerHTML = (h === 'home' ? '' : enNote()) + fn();
  $('#ftr').innerHTML = footer();
  document.documentElement.lang = state.lang === 'en' ? 'en' : 'uk';
  document.title = 'BADVASY — ' + (h === 'home' ? T('дистрибуція та фасування ЗЗР і добрив', 'crop protection and fertilizers') : (($('#main h1') || {}).textContent || ''));
  window.scrollTo(0, 0);
  if (h === 'contacts-social') setTimeout(() => { const s = $('#social'); s && s.scrollIntoView({ behavior: 'smooth' }); }, 60);
  if (h === 'partnership-suppliers') setTimeout(() => { const s = $('#suppliers'); s && s.scrollIntoView({ behavior: 'smooth', block: 'center' }); }, 60);
  initChrome(); initReveal(); if (h === 'home') initHome(); initFooterMark(); initBrandsAcc();
}
