/* ===================== ПОВЕДІНКА (з v2.js дизайнера) ===================== */
let hdrScrollBound = false;
function initChrome() {
  const hdr = $('#hdr');
  if (!hdrScrollBound) { hdrScrollBound = true; addEventListener('scroll', () => { const bar = $('.bar'); if (bar) hdr.classList.toggle('is-stuck', bar.getBoundingClientRect().top <= 0.5 && scrollY > 60); }, { passive: true }); }
  /* компактні випадаючі списки */
  let closeT = 0;
  const lis = $$('.nav .ni');
  const close = () => lis.forEach(li => { li.classList.remove('open'); const b = $('button.nl', li); b && b.setAttribute('aria-expanded', 'false'); });
  lis.forEach(li => {
    const b = $('button.nl', li); if (!b) { li.addEventListener('mouseenter', close); return; }
    const open = () => { clearTimeout(closeT); close(); li.classList.add('open'); b.setAttribute('aria-expanded', 'true'); };
    li.addEventListener('mouseenter', open);
    li.addEventListener('mouseleave', () => { clearTimeout(closeT); closeT = setTimeout(close, 160); });
    b.addEventListener('click', () => li.classList.contains('open') ? close() : open());
  });
  document.onkeydown = e => { if (e.key === 'Escape') { close(); const s = $('#srch'); s && s.classList.remove('open'); } };
  document.onclick = e => { if (!e.target.closest('.nav')) close(); };
  const burger = $('.burger'), mob = $('#mob');
  burger && burger.addEventListener('click', () => { const o = burger.getAttribute('aria-expanded') !== 'true'; burger.setAttribute('aria-expanded', String(o)); mob.hidden = !o; });
  $$('[data-search]').forEach(b => b.addEventListener('click', openSearch));
}
document.addEventListener('click', e => {
  const l = e.target.closest('[data-lang]');
  if (l) { state.lang = l.dataset.lang; try { localStorage.setItem('bv-lang', state.lang); } catch (x) {} render(); return; }
  if (e.target.closest('[data-file]')) { e.preventDefault(); alert('У прототипі файли звітності не підключені.'); }
});
